import{_ as r}from"./chunks/panel-workspace.DfVZw37W.js";import{_ as n,a as i,b as s}from"./chunks/theme-dark.DMCpB48j.js";import{_ as l,C as d,o as g,c as h,a2 as a,j as p,a as t,E as c}from"./chunks/framework.Dx-TCpNt.js";const _=JSON.parse('{"title":"Introduction","description":"KomaYomi — Manga Learner — is a local-first web app for reading manga in more than one language at once. Maybe you are learning Japanese with one eye on…","frontmatter":{"description":"KomaYomi — Manga Learner — is a local-first web app for reading manga in more than one language at once. Maybe you are learning Japanese with one eye on…"},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1794778665000}'),m={name:"guide/introduction.md"};function u(f,e,b,y,w,v){const o=d("Badge");return g(),h("div",null,[e[2]||(e[2]=a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>KomaYomi — <strong>Manga Learner</strong> — is a local-first web app for reading manga in more than one language at once. Maybe you are learning Japanese with one eye on the translation, maybe you are doing scanlation and want to check your typesetting against the raw, maybe you just need to know how that one line was handled in the official release. KomaYomi splits a page into panels, lines up the same panel across Japanese, Chinese and English, and lets you pin Markdown notes — TL notes, typesetting questions, vocabulary — to the exact panel they belong to.</p><p>It is neither a general-purpose manga reader nor a distribution platform. Everything runs on your own machine, against your own image folders.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Translations are easiest to study panel by panel, not page by page. But three scans of the same book almost never line up: the page is shifted, the panel is cropped differently, the lettering sits somewhere else. A normal image viewer gives you one zoom level, no notes, and no way to say &quot;this balloon, in these three editions&quot;.</p><p>KomaYomi adds the missing middle layer:</p><ol><li><strong>Structure</strong> — panels are detected and stored as normalized rectangles, so your boxes survive any zoom, window size or export resolution.</li><li><strong>Alignment</strong> — each language can be nudged independently until the same panel really overlaps. Yes, finally.</li><li><strong>Notes</strong> — every remark is scoped to a page or a panel, in Markdown, with tags and sources. &quot;I&#39;ll remember it later&quot; is no longer a plan.</li></ol><h2 id="the-workflow" tabindex="-1">The workflow <a class="header-anchor" href="#the-workflow" aria-label="Permalink to &quot;The workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>What you do</th><th>Page</th></tr></thead><tbody><tr><td>1</td><td>Get the scans in order: <code>raw/&lt;volume&gt;/&lt;language&gt;/&lt;chapter&gt;/01.jpg</code>, or point the app at a folder you already have.</td><td><a href="/KomaYomi-docs/guide/preprocess">Preparing &amp; Renaming Images</a>, <a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a></td></tr><tr><td>2</td><td>Open a page, let it auto-split, then fix the boxes by hand. Detection is a draft, not a verdict.</td><td><a href="/KomaYomi-docs/guide/panels">Panel Workbench</a></td></tr><tr><td>3</td><td>Read 2–3 languages side by side or in overlay, align them, mask the ones you are testing yourself on.</td><td><a href="/KomaYomi-docs/guide/compare">Compare Reader</a></td></tr><tr><td>4</td><td>Write page and panel notes with tags, sources and screenshots. TL notes very much welcome.</td><td><a href="/KomaYomi-docs/guide/notes">Notes</a></td></tr><tr><td>5</td><td>Export a study HTML, PNGs for slides, or a project package for another machine.</td><td><a href="/KomaYomi-docs/guide/export">Export</a></td></tr></tbody></table><h2 id="a-tour-of-the-screen" tabindex="-1">A tour of the screen <a class="header-anchor" href="#a-tour-of-the-screen" aria-label="Permalink to &quot;A tour of the screen&quot;">​</a></h2><figure class="shot"><img src="'+r+'" alt="Panel workbench with a manga page, detected panels, resize handles and the annotation toolbar"><figcaption>The panel workbench. Top bar: page navigation, Panels / Compare, reading order, theme, interface language, Notes and Export. Left: library. Right: notes. Middle: the page with panel boxes — where you will spend most of your time.</figcaption></figure><p>The window has five regions that never move, so muscle memory can take over:</p><ul><li><strong>Top bar</strong> — brand (back to the library), volume / chapter / page, <code>‹</code> <code>›</code> page arrows, the save indicator, the <strong>Panels / Compare</strong> switch, the reading-direction selector, the UI theme, the interface language, <strong>Notes</strong> and <strong>Export</strong>.</li><li><strong>Library sidebar</strong> (<code>S</code>) — volumes → chapters → pages, with per-page warnings and the entry points for adding a manga, folder rules, project files, exchange files and backup.</li><li><strong>Stage</strong> — the panel workbench or the compare reader, depending on the view switch.</li><li><strong>Notes column</strong> (<code>N</code>) — page notes, panel notes, overview search and the scratchpad.</li><li><strong>Pane splitters</strong> — drag the vertical handle between library and stage, or between stage and notes, to resize; double-click to reset.</li></ul><p>A page can carry any number of languages. The language chips in the compare reader are enabled only for languages that exist on the current page.</p><h2 id="the-first-ten-minutes" tabindex="-1">The first ten minutes <a class="header-anchor" href="#the-first-ten-minutes" aria-label="Permalink to &quot;The first ten minutes&quot;">​</a></h2><ol><li>Get the app running — <code>npm run dev</code> from the repo, or just launch the desktop build — then open <code>http://127.0.0.1:5173</code> in your browser.</li><li>Give the library something to read: drop a volume into <code>raw/</code>, or click <strong>＋ Add manga</strong> in the sidebar and pick a folder you already have.</li><li>Open any page from the sidebar. The first visit splits it into panels automatically and keeps the result in <code>data/pages/</code>.</li><li>To read two languages against each other, switch to <strong>Compare</strong> (<code>C</code>), tick <code>JA</code> and <code>ZH</code>, and drag one pane until the same panel lines up in both. Working panel by panel is much easier than nudging the whole page.</li><li>When something is worth keeping, open <strong>Notes</strong> (<code>N</code>), select a panel, and write your first note. <code>Ctrl+Enter</code> saves it.</li><li>Finally, press <code>E</code> to export an HTML file and open it in your browser to see how it reads.</li></ol><h2 id="what-is-implemented" tabindex="-1">What is implemented <a class="header-anchor" href="#what-is-implemented" aria-label="Permalink to &quot;What is implemented&quot;">​</a></h2><div class="status-list"><div><strong>Library</strong> — scans volumes, recognizes language folder aliases, pairs pages by sorted position, warns about missing pages and naming mismatches.</div><div><strong>Panels</strong> — automatic XY-cut detection, add / move / eight-direction resize / merge / group / delete, numbering, percentage inputs, grid generator, panel templates, declarative layouts, plugins, cross-session page history.</div><div><strong>Annotations</strong> — arrow, rectangle, ellipse, highlighter, freehand pen, text, number badge and mosaic, page-level visibility switch, PNG export support.</div><div><strong>Compare</strong> — 2–3 languages, side-by-side or overlay, per-language blur/solid masks, wheel zoom, pan, page/panel/anchor/grid alignment, saved presets, custom language order.</div><div><strong>Notes</strong> — page/panel notes, Markdown with a toolbar and live preview, tags, sources, attached images, overview search, copy-for-LLM, scratchpad.</div><div><strong>Export</strong> — HTML (image folder or single file), PNG (whole page, current panel, trilingual collage), PDF via the browser print dialog, Word (`.docx`) with page images and notes, panel-border overlay, print styles, export templates.</div><div><strong>Storage</strong> — local folders, mounted network shares and WebDAV, with on-demand image fetching and a bounded LRU cache.</div><div><strong>Portability</strong> — `.mnproj` project packages, `.mntpl` / `.mnexp` / `.mnpage.json` exchange files, backup and restore ZIPs, versioned schemas.</div></div><h2 id="what-is-not-implemented" tabindex="-1">What is not implemented <a class="header-anchor" href="#what-is-not-implemented" aria-label="Permalink to &quot;What is not implemented&quot;">​</a></h2>',19)),p("p",null,[e[0]||(e[0]=t("These items are marked ",-1)),c(o,{type:"warning",text:"Planned"}),e[1]||(e[1]=t(" wherever they appear:",-1))]),e[3]||(e[3]=a('<ul><li>Vocabulary-list export. PDF and Word are available as <strong>PDF (print)</strong> and <strong>Word document</strong> in the export dialog.</li><li>Scheduled automatic backups.</li><li>An in-app image converter or batch renamer. Prepare files before importing (see <a href="/KomaYomi-docs/guide/preprocess">Preparing &amp; Renaming Images</a>).</li><li>A native mobile app. The web UI does work in a narrow browser window (see below).</li></ul><figure class="shot"><img src="'+n+'" alt="Compare reader in a narrow window with the language panes stacked vertically"><figcaption>Narrow window: panes stack vertically, the library becomes a drawer. A responsive web layout, not a native app — but it still works on a phone-sized screen.</figcaption></figure><h2 id="light-and-dark" tabindex="-1">Light and dark <a class="header-anchor" href="#light-and-dark" aria-label="Permalink to &quot;Light and dark&quot;">​</a></h2><p>The UI theme follows the system by default and can be fixed to light or dark from the top bar. The exported HTML is light-only, so screenshots and printouts stay consistent.</p><figure class="shot"><img src="'+i+'" alt="Compare reader in the light theme"><figcaption>Light theme.</figcaption></figure><figure class="shot"><img src="'+s+'" alt="Compare reader in the dark theme"><figcaption>Dark theme.</figcaption></figure><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>Nothing appears in the library.</strong> The sidebar only scans <code>raw/</code>; add a folder or mount a remote tree first. See <a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a>.</li><li><strong>Panels are wrong on the first page.</strong> Detection is a draft, not a verdict. Fix the boxes before writing panel notes; re-running detection later discards hand edits.</li><li><strong>A language chip is greyed out.</strong> That language has no image on this page. Check page counts and the volume language mapping.</li><li><strong>Notes seem to disappear on another machine.</strong> Notes live in <code>data/</code>, images in <code>raw/</code>; move both, or export a <code>.mnproj</code>. See <a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a>.</li><li><strong>An image request fails offline.</strong> Only pages that were opened before going offline are cached. See <a href="/KomaYomi-docs/guide/remote">Remote Storage &amp; Backup</a>.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>New install: <a href="/KomaYomi-docs/guide/installation">Install &amp; Run</a>.</li><li>Images not ready yet: <a href="/KomaYomi-docs/guide/preprocess">Preparing &amp; Renaming Images</a>.</li><li>Ready to add images: <a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a>.</li><li>Folders have an unusual shape: <a href="/KomaYomi-docs/guide/folder-rules">Folder Detection Rules</a>.</li><li>Looking for a key: <a href="/KomaYomi-docs/guide/shortcuts">Keyboard Shortcuts</a>.</li><li>Something is wrong: <a href="/KomaYomi-docs/faq">FAQ &amp; Troubleshooting</a>.</li></ul>',10))])}const P=l(m,[["render",u]]);export{_ as __pageData,P as default};
